def valid_variant(count,version,variant):
    return type(variant)is int and (variant==0 or version==4 and count==18 and variant in PREFIX18)

def pairings(clubs,requested,legs=2,variant=0):
    n=len(clubs)
    if not valid_variant(n,4,variant):raise ValueError('Invalid saved schedule variant')
    patterns=PREFIX18[variant] if variant else PATTERNS.get(n)
    if patterns is None:
        from mirrored_schedule import pairings as previous
        return previous(clubs,requested,legs)
    half=n if n%2 else n-1
    if requested<0 or requested>=half*legs:return []
    leg,rotation=divmod(requested,half)
    ids=([-1]+list(range(n))) if n%2 else list(range(n))
    rest=ids[1:];rest=rest[-rotation:]+rest[:-rotation] if rotation else rest
    order=[ids[0]]+rest;result=[];slot=0
    for i in range(len(ids)//2):
        a,b=order[i],order[-1-i]
        if a<0 or b<0:continue
        if patterns[rotation][slot]=='0':a,b=b,a
        if leg%2:a,b=b,a
        result.append((clubs[a],clubs[b]));slot+=1
    return result

def venues(league):
    result={c.uid or c.name:[] for c in league.clubs}
    for r in range(league.total_rounds):
        for h,a in league.pairings(r):
            result[h.uid or h.name].append((r,'H'));result[a.uid or a.name].append((r,'A'))
    return result

def repeats(rows,from_round=0):
    return sum(a[1]==b[1] for a,b in zip(rows,rows[1:]) if b[0]>=from_round)

def upgrade_if_compatible(league,player_uid=None):
    if league.schedule_version>=4 or len(league.clubs)not in PATTERNS:return False
    count=len(league.clubs);played=league.round_index
    if league.format_key and played:
        from domestic_formats import specification
        phases=specification(league)['phases']
        if len(phases)!=1 or phases[0]['legs']!=2:return False
    variant=played if count==18 and league.schedule_version==3 and played in PREFIX18 else 0
    before=venues(league)
    key=lambda pairs:[(h.uid or h.name,a.uid or a.name)for h,a in pairs]
    past=[key(league.pairings(r))for r in range(played)]
    old=league.schedule_version;old_variant=getattr(league,'schedule_variant',0)
    league.schedule_version=4;league.schedule_variant=variant
    after=venues(league)
    safe=all(key(league.pairings(r))==row for r,row in enumerate(past))
    better=sum(repeats(r,played)for r in after.values())<sum(repeats(r,played)for r in before.values())
    personal=(not player_uid or player_uid not in before or repeats(after[player_uid],played)<=repeats(before[player_uid],played))
    if safe and better and personal:return True
    league.schedule_version=old;league.schedule_variant=old_variant;return False
